values
('vocab_monetary','monetary','adjective','related to money or financial value','[{"senseId":"monetary_1","meaning":"related to money or financial value","acceptedParaphrases":["financial","money-related"],"masteryContexts":[{"contextId":"u1_31_monetary_meaning","text":"The trophy has little monetary value, but it means a great deal to the winners.","meaning":"connected with money or payment"},{"contextId":"u1_31_monetary_paraphrase","text":"Volunteers receive no monetary reward for helping at the tournament, only a free t-shirt.","meaning":"involving financial value"}],"contextDependentParaphrases":[],"misleadingDistractors":["physical","historic","personal"]}]'::jsonb,'[]'::jsonb,'["monetary value","monetary reward"]'::jsonb,'live'),
('vocab_estimated','estimated','adjective','calculated or judged approximately rather than known exactly','[{"senseId":"estimated_1","meaning":"calculated or judged approximately rather than known exactly","acceptedParaphrases":["approximate","roughly calculated"],"masteryContexts":[{"contextId":"u1_32_estimated_meaning","text":"The estimated crowd at the final was fifty thousand, though officials admitted that nobody had counted exactly.","meaning":"worked out approximately, not exactly"},{"contextId":"u1_32_estimated_paraphrase","text":"The estimated cost of the new stadium is two hundred million pounds, but the final bill may be higher.","meaning":"based on calculation rather than certainty"}],"contextDependentParaphrases":[],"misleadingDistractors":["confirmed","exact","historic"]}]'::jsonb,'[]'::jsonb,'["estimated cost","estimated number"]'::jsonb,'live'),
('vocab_struggle','struggle','verb','to have difficulty doing or achieving something','[{"senseId":"struggle_1","meaning":"to have difficulty doing or achieving something","acceptedParaphrases":["have difficulty","find it hard"],"masteryContexts":[{"contextId":"u1_33_struggle_meaning","text":"Some beginners struggle to maintain their balance on the board.","meaning":"have great difficulty doing something"},{"contextId":"u1_33_struggle_paraphrase","text":"A new player often struggles to control the ball at first.","meaning":"need much effort because something is hard"}],"contextDependentParaphrases":[],"misleadingDistractors":["succeed easily","permit","recommend"],"grammarForms":{"base":"struggle","thirdPerson":"struggles","past":"struggled","pastParticiple":"struggled","ing":"struggling"},"grammarPatterns":["struggle + to-infinitive","struggle with + noun"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_minimum','minimum','noun','the smallest amount, number, or level allowed or needed','[{"senseId":"minimum_1","meaning":"the smallest amount, number, or level allowed or needed","acceptedParaphrases":["lowest amount","least"],"masteryContexts":[{"contextId":"u1_34_minimum_meaning","text":"Players must complete a minimum of three training sessions each week.","meaning":"lowest acceptable amount or level"},{"contextId":"u1_34_minimum_paraphrase","text":"The minimum age for competitors is sixteen.","meaning":"smallest quantity that meets a requirement"}],"contextDependentParaphrases":[],"misleadingDistractors":["maximum","average","estimate"],"teacherNote":"Often paraphrased structurally as at least rather than by a direct noun synonym."}]'::jsonb,'[]'::jsonb,'["minimum age","minimum requirement"]'::jsonb,'live'),
('vocab_championship','championship','noun','a major competition that decides the best player or team','[{"senseId":"championship_1","meaning":"a major competition that decides the best player or team","acceptedParaphrases":["title competition","major contest"],"masteryContexts":[{"contextId":"u1_35_championship_meaning","text":"She qualified for the national championship after winning the regional event.","meaning":"major contest deciding the title winner"},{"contextId":"u1_35_championship_paraphrase","text":"He trained all year for the championship.","meaning":"competition that determines the leading player"}],"contextDependentParaphrases":[],"misleadingDistractors":["practice session","friendly match","lesson"]}]'::jsonb,'[]'::jsonb,'["national championship","win the championship"]'::jsonb,'live'),
('vocab_competitor','competitor','noun','a person or organisation taking part in a competition','[{"senseId":"competitor_1","meaning":"a person or organisation taking part in a competition","acceptedParaphrases":["contestant","participant in a competition"],"masteryContexts":[{"contextId":"u1_36_competitor_meaning","text":"Each competitor must register before the race begins.","meaning":"person taking part in a contest"},{"contextId":"u1_36_competitor_paraphrase","text":"Every competitor receives a number before the event starts.","meaning":"participant trying to win a competition"}],"contextDependentParaphrases":[],"misleadingDistractors":["spectator","coach","organiser"]}]'::jsonb,'["compete","competition","competitive"]'::jsonb,'["strong competitor","fellow competitor"]'::jsonb,'live'),
('vocab_relatively','relatively','adverb','to a fairly limited degree when compared with something else','[{"senseId":"relatively_1","meaning":"to a fairly limited degree when compared with something else","acceptedParaphrases":["comparatively","fairly"],"masteryContexts":[{"contextId":"u1_37_relatively_meaning","text":"The new sports centre is relatively small compared with the old stadium.","meaning":"to a degree judged by comparison"},{"contextId":"u1_37_relatively_paraphrase","text":"The route is relatively easy compared with the mountain course.","meaning":"fairly so compared with something else"}],"contextDependentParaphrases":[],"misleadingDistractors":["completely","extremely","exactly"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_patience','patience','noun','the ability to remain calm while waiting or dealing with difficulty','[{"senseId":"patience_1","meaning":"the ability to remain calm while waiting or dealing with difficulty","acceptedParaphrases":["ability to wait calmly","calm persistence"],"masteryContexts":[{"contextId":"u1_38_patience_meaning","text":"Learning a difficult skill takes patience and regular practice.","meaning":"ability to stay calm while waiting"},{"contextId":"u1_38_patience_paraphrase","text":"Coaching young beginners requires patience.","meaning":"calm persistence despite difficulty"}],"contextDependentParaphrases":[],"misleadingDistractors":["speed","strength","pressure"]}]'::jsonb,'["patient","patiently"]'::jsonb,'["show patience","require patience"]'::jsonb,'live'),
('vocab_atmosphere','atmosphere','noun','the feeling or mood created in a place or situation','[{"senseId":"atmosphere_1","meaning":"the feeling or mood created in a place or situation","acceptedParaphrases":["mood","feeling"],"masteryContexts":[{"contextId":"u1_39_atmosphere_meaning","text":"The crowd created an exciting atmosphere before the match.","meaning":"overall mood felt in a place"},{"contextId":"u1_39_atmosphere_paraphrase","text":"Music and cheering created a positive atmosphere in the stadium.","meaning":"emotional feeling created by a setting"}],"contextDependentParaphrases":[],"misleadingDistractors":["temperature","schedule","audience"]}]'::jsonb,'[]'::jsonb,'["friendly atmosphere","create an atmosphere"]'::jsonb,'live'),
('vocab_incredible','incredible','adjective','extremely impressive, surprising, or difficult to believe','[{"senseId":"incredible_1","meaning":"extremely impressive, surprising, or difficult to believe","acceptedParaphrases":["amazing","extraordinary"],"masteryContexts":[{"contextId":"u1_40_incredible_meaning","text":"Her final lap was incredible and broke the school record.","meaning":"extremely impressive or surprising"},{"contextId":"u1_40_incredible_paraphrase","text":"The goalkeeper made an incredible save in the final seconds.","meaning":"exceptionally remarkable and hard to believe"}],"contextDependentParaphrases":[],"misleadingDistractors":["ordinary","predictable","minor"]}]'::jsonb,'["incredibly","incredibility"]'::jsonb,'[]'::jsonb,'live')
